// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 firstAmount, uint256 secondAmount, address actor) public {
        vm.assume(actor != address(c) && actor != address(this));
        vm.assume(firstAmount <= type(uint256).max / 2 && secondAmount <= type(uint256).max / 2);
        vm.deal(actor, firstAmount + secondAmount);

        vm.prank(actor);
        c.addToBalance{value: firstAmount}();
        uint256 before = c.getBalance(actor);

        vm.prank(actor);
        bool ok;
        try c.addToBalance{value: secondAmount}() { ok = true; } catch { ok = false; }

        // Universal rule: a successful deposit must record exactly prior + secondAmount;
        // an amount that would overflow the recorded balance must cause the call to revert
        // rather than silently wrap the stored balance.
        assertTrue(!ok || c.getBalance(actor) == before + secondAmount);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        // overflow-range deposit: two such deposits exceed the uint256 maximum
        amount = bound(amount, 2 ** 255, type(uint256).max);
        vm.deal(actor, amount * 2);

        vm.prank(actor);
        c.addToBalance{value: amount}();

        vm.prank(actor);
        try c.addToBalance{value: amount}() {
            // second deposit accepted in the buggy variant (wraps)
        } catch {
            // guard in the reference reverts the overflowing deposit
        }

        // INVARIANT: the recorded balance is never a wrapped-around value;
        // after these two deposits of `amount` each, a correct contract's
        // balance for `actor` equals `amount` (second deposit rejected),
        // never a wrapped residue.
        assertTrue(c.getBalance(actor) == amount);
    }
}

