pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(this) && actor != address(c));
        uint256 before = c.getBalance(actor);
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.addToBalance{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 expected;
        unchecked { expected = before + amount; }
        assertTrue(
            ok ? (c.getBalance(actor) == expected && expected >= before)
              : (c.getBalance(actor) == before),
            "balance must increase by exactly msg.value or the deposit must revert"
        );
    }
}

