pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint96 v1, uint256 v2, address actor) public {
        vm.assume(actor != address(0));
        v1 = uint96(bound(v1, 1, 1e18));
        // keep v2 wide; the fuzzer may pick an overflow-range value
        v2 = bound(v2, 0, type(uint256).max);

        uint256 before = c.getBalance(actor);

        vm.deal(actor, v1);
        vm.prank(actor);
        c.addToBalance{value: v1}();

        vm.deal(actor, v2);
        bool ok;
        vm.prank(actor);
        try c.addToBalance{value: v2}() { ok = true; } catch { ok = false; }

        assertTrue(!ok || c.getBalance(actor) > before);
    }
}

