pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint96 firstAmount, uint256 secondAmount, address actor) public {
        vm.assume(actor != address(0));
        // drive the second deposit into the overflow region of first + second
        secondAmount = bound(secondAmount, type(uint256).max - uint256(firstAmount) + 1, type(uint256).max);

        vm.deal(actor, uint256(firstAmount));
        vm.prank(actor);
        c.addToBalance{value: firstAmount}();
        uint256 afterFirst = c.getBalance(actor);

        vm.deal(actor, secondAmount);
        vm.prank(actor);
        bool ok;
        try c.addToBalance{value: secondAmount}() { ok = true; } catch { ok = false; }

        // RULE: a successful deposit records the exact arithmetic sum; a failed one changes nothing.
        assertTrue(!ok ? c.getBalance(actor) == afterFirst : c.getBalance(actor) == afterFirst + secondAmount);
    }
}

