pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1, type(uint256).max / 2);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();
        assertEq(address(c).balance, amount, "contract holds deposit");
        vm.prank(actor);
        bool ok;
        try c.withdrawBalance() { ok = true; } catch { ok = false; }
        assertTrue(ok && address(c).balance == 0 && actor.balance == amount, "withdrawal must transfer full balance out of the contract");
    }
}

