    function testZeroValueDeposit() public {
        bool reverted = false;
        // state-changing call as top-level statement, wrapped via try-style bool capture
        bytes memory ret;
        (bool ok, bytes memory data) = address(c).call(abi.encodeWithSignature("addToBalance()"));
        ret = data;
        reverted = !ok;
        assert(!reverted);
    }

    receive() external payable {}
    fallback() external payable {}
}

